-- V1: identity and language settings (DB-02). Design: docs/database/schema.md, sections 3.1 and 5.
-- Conventions: uuid keys generated by the app (UUIDv7), text + CHECK for enums,
-- timestamptz for instants, named constraints so violations can be mapped to API errors.

-- Languages: ISO 639-1 code as natural key ------------------------------------------------
create table languages (
    code                     text primary key,
    name                     text    not null,
    native_name              text    not null,
    supported_as_target      boolean not null,
    supported_as_explanation boolean not null,
    constraint languages_code_format_ck check (code ~ '^[a-z]{2,3}$')
);

insert into languages (code, name, native_name, supported_as_target, supported_as_explanation)
values ('de', 'German', 'Deutsch', true, true),
       ('en', 'English', 'English', false, true);

-- Users -----------------------------------------------------------------------------------
create table users (
    id                      uuid primary key,
    email                   text        not null,
    password_hash           text        not null,
    display_name            text        not null,
    role                    text        not null default 'USER',
    enabled                 boolean     not null default true,
    email_verified_at       timestamptz,
    interface_language_code text        not null default 'en',
    timezone                text        not null default 'UTC',
    last_login_at           timestamptz,
    created_at              timestamptz not null default now(),
    updated_at              timestamptz not null default now(),
    constraint users_email_length_ck check (char_length(email) between 3 and 320),
    constraint users_display_name_length_ck check (char_length(display_name) between 1 and 100),
    constraint users_role_ck check (role in ('USER', 'ADMIN')),
    constraint users_interface_language_fk foreign key (interface_language_code) references languages (code)
);

-- Case-insensitive uniqueness: "Anna@x.de" and "anna@x.de" are the same account
create unique index users_email_lower_uq on users (lower(email));

-- Refresh tokens (rotating, stored hashed; reuse of a rotated token revokes the family) -----
create table refresh_tokens (
    id             uuid primary key,
    user_id        uuid        not null,
    token_hash     text        not null,
    family_id      uuid        not null,
    expires_at     timestamptz not null,
    revoked_at     timestamptz,
    replaced_by_id uuid,
    user_agent     text,
    created_at     timestamptz not null default now(),
    constraint refresh_tokens_token_hash_uq unique (token_hash),
    constraint refresh_tokens_user_fk foreign key (user_id) references users (id) on delete cascade,
    constraint refresh_tokens_replaced_by_fk foreign key (replaced_by_id) references refresh_tokens (id)
        on delete set null
);

create index refresh_tokens_user_ix on refresh_tokens (user_id);
create index refresh_tokens_family_ix on refresh_tokens (family_id);

-- Learner profile per target language; target of every learning table's composite FK -------
create table user_languages (
    user_id                   uuid        not null,
    language_code             text        not null,
    explanation_language_code text        not null,
    self_assessed_level       text,
    active                    boolean     not null default false,
    daily_review_goal         int         not null default 50,
    new_cards_per_day         int         not null default 20,
    preferred_exercise_types  text[]      not null default '{}',
    practice_session_length   int         not null default 20,
    created_at                timestamptz not null default now(),
    updated_at                timestamptz not null default now(),
    constraint user_languages_pk primary key (user_id, language_code),
    constraint user_languages_user_fk foreign key (user_id) references users (id) on delete cascade,
    constraint user_languages_language_fk foreign key (language_code) references languages (code),
    constraint user_languages_explanation_language_fk foreign key (explanation_language_code)
        references languages (code),
    constraint user_languages_explanation_differs_ck check (explanation_language_code <> language_code),
    constraint user_languages_level_ck check (self_assessed_level in ('A1', 'A2', 'B1', 'B2', 'C1', 'C2')),
    constraint user_languages_daily_review_goal_ck check (daily_review_goal between 1 and 1000),
    constraint user_languages_new_cards_per_day_ck check (new_cards_per_day between 0 and 500),
    constraint user_languages_session_length_ck check (practice_session_length between 5 and 200)
);

-- At most one active language per user
create unique index user_languages_one_active_uq on user_languages (user_id) where active;
